/** A person's score from their settled figures (two decimals, see personSplit) and their overdue count: the settled
 *  figures / 100, minus 5 for every overdue claim, rounded once, half to even, to a whole number. */
export function score(settled: string, overdueCount: number): string {
  const [whole, frac = ''] = settled.replace('-', '').split('.');
  const h = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const p = (settled.startsWith('-') ? -h : h) - 50000n * BigInt(overdueCount); // in 1/10000 of the score
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && q % 2n === 1n) ? q + 1n : q;
  return String(p < 0n ? -r : r);
}

/** A person's band from their score (see score) and the sheet's score thresholds: HIGH at or above the high one, MID at
 *  or above the mid one, else LOW; empty while either threshold is blank. */
export function band(score: string, mid: string | null, high: string | null): string {
  if (mid === null || high === null) return '';
  const s = BigInt(score);
  return s >= BigInt(high) ? 'HIGH' : s >= BigInt(mid) ? 'MID' : 'LOW';
}
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { overdue } from '../overdue/overdue';
import { type Person } from '../people/people';
import { personSplit, useRates } from '../rates/rates';
import { useFloor, useLate, useScoreThresholds } from '../settings/settings';
import { band, score } from './score';

function ScoreHead() {
  return (
    <>
      <th>Score</th>
      <th>Band</th>
    </>
  );
}

/** A person's score (see score), and their band by it (see band), over their claims that count in the live totals. */
function PersonScore({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const mine = live(claims.data?.filter((c) => c.personId === person.id) ?? [], [person], late.today);
  const settled = personSplit(mine, rates.data, person, late, floor).settled;
  const count = overdue(mine, rates.data, person, late, floor).count;
  const thresholds = useScoreThresholds(sheetId);
  const shown = score(settled, count);
  return (
    <>
      <td data-testid="person-score">{shown}</td>
      <td data-testid="person-band">{band(shown, thresholds.mid, thresholds.high)}</td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 26, Component: ScoreHead }),
  PersonRow.fill({ order: 26, Component: PersonScore }),
];
